,p_event_id=>wwv_flow_imp.id(37691519785141201)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'function checkProgress() {',
    '    apex.server.process(''GET_RECALC_PROGRESS'').then((data) => {',
    '        if (data.done) {',
    '            apex.message.showPageSuccess(''Recalculation '' + data.status.toLowerCase() +',
    '                '': '' + data.sofar.toLocaleString() + '' orders.'');',
    '        } else {',
    '            apex.message.showPageSuccess(data.totalwork',
    '                ? ''Recalculating order totals: '' + data.sofar.toLocaleString() +',
    unistr('                  '' of '' + data.totalwork.toLocaleString() + '' orders\2026'''),
    unistr('                : ''Recalculation: '' + data.status + ''\2026'');'),
    '            setTimeout(checkProgress, 1000);',
    '        }',
    '    });',
    '}',
    'checkProgress();')))).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37545089846772803)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Approve Selected Orders'
,p_static_id=>'approve-selected-orders'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for r in (',
'    select column_value as order_id',
'      from apex_string.split(:P8_SELECTED_ORDERS, '':'')',
') loop',
'    orb_sales.approve_order(p_order_id => r.order_id);',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(37544952931772802)
,p_process_success_message=>'&{THE_SELECTED_ORDERS_HAVE_BEEN_APPROVED}.'
,p_security_scheme=>wwv_flow_imp.id(37795609922513818)
,p_internal_uid=>37545089846772803
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37665235830117302)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_RECALC_PROGRESS'
,p_static_id=>'get-recalc-progress'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_done boolean := true;',
'begin',
'    apex_json.open_object;',
'    for s in (',
'        select status, status_code, sofar, totalwork',
'          from apex_appl_page_bg_proc_status',
'         where execution_id = :P8_RECALC_ID',
'    ) loop',
'        l_done := s.status_code in (''SUCCESS'', ''FAILED'', ''ABORTED'');',
'        apex_json.write(''status'',    s.status);',
'        apex_json.write(''sofar'',     s.sofar);',
'        apex_json.write(''totalwork'', s.totalwork);',
'    end loop;',
'    apex_json.write(''done'', l_done);',
'    apex_json.close_object;',
'',
'    if l_done then',
'        apex_util.set_session_state(''P8_RECALC_ID'', null);',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>37665235830117302
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37574761560855603)
,p_process_sequence=>30
,p_parent_process_id=>wwv_flow_imp.id(37574693011855602)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Recalculate Order Totals'
,p_static_id=>'recalculate-order-totals'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_total pls_integer;',
'    l_done  pls_integer := 0;',
'begin',
'    select count(*) into l_total from orb_orders;',
'    for o in (select order_id from orb_orders) loop',
'        orb_sales.recalc_order_total(p_order_id => o.order_id);',
'        l_done := l_done + 1;',
'        if mod(l_done, 100) = 0 or l_done = l_total then',
'            apex_background_process.set_progress(',
'                p_totalwork => l_total,',
'                p_sofar     => l_done);',
'        end if;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>37574761560855603
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37574693011855602)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_EXECUTION_CHAIN'
,p_process_name=>'Recalculate Totals'
,p_static_id=>'recalculate-totals'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'return_id_into_item', 'P8_RECALC_ID',
  'run_in_background', 'Y',
