,p_title=>'&{PRODUCT_CATEGORIES}.'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with nodes as (',
'    select ''C'' || category_id                               as id,',
'           nvl2(parent_category_id, ''C'' || parent_category_id, null) as parent_id,',
'           category_name                                    as title,',
'           ''fa-folder-o''                                    as icon,',
'           null                                             as link,',
'           category_name                                    as sort_key',
'      from orb_categories',
'    union all',
'    select ''P'' || product_id,',
'           ''C'' || category_id,',
'           product_name,',
'           ''fa-tag'',',
'           apex_page.get_url(p_page   => 12,',
'                             p_items  => ''P12_PRODUCT_ID'',',
'                             p_values => product_id),',
'           product_name',
'      from orb_products',
')',
'select case when connect_by_isleaf = 1 then 0',
'            when level = 1             then 1',
'            else                            -1',
'       end         as status,',
'       level,',
'       title,',
'       icon,',
'       id          as value,',
'       title       as tooltip,',
'       link',
'  from nodes',
' start with parent_id is null',
' connect by prior id = parent_id',
' order siblings by sort_key'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_JSTREE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'activate_node_link_with', 'S',
