prompt --application/deployment/definition
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '-- Removes every Orbit Outfitters object from the current schema.'||chr(10);
wwv_flow_imp.g_varchar2_table(2) := 'begin'||chr(10);
wwv_flow_imp.g_varchar2_table(3) := '    for o in (select object_name, object_type from user_objects'||chr(10);
wwv_flow_imp.g_varchar2_table(4) := '               where object_name like ''ORB\_%'' escape ''\'''||chr(10);
wwv_flow_imp.g_varchar2_table(5) := '                 and object_type in (''VIEW'', ''PACKAGE'', ''SEQUENCE'', ''TABLE'')'||chr(10);
wwv_flow_imp.g_varchar2_table(6) := '               order by decode(object_type, ''VIEW'', 1, ''PACKAGE'', 2, ''SEQUENCE'', 3, 4)) loop'||chr(10);
wwv_flow_imp.g_varchar2_table(7) := '        execute immediate ''drop '' || o.object_type || '' '' || o.object_name'||chr(10);
wwv_flow_imp.g_varchar2_table(8) := '                       || case o.object_type when ''TABLE'' then '' cascade constraints purge'' end;'||chr(10);
wwv_flow_imp.g_varchar2_table(9) := '    end loop;'||chr(10);
wwv_flow_imp.g_varchar2_table(10) := 'end;'||chr(10);
wwv_flow_imp.g_varchar2_table(11) := '/'||chr(10);
wwv_flow_imp_shared.create_install(
 p_id=>wwv_flow_imp.id(39911000000000000)
,p_welcome_message=>'This installs the Orbit Outfitters sample schema of the book Oracle APEX 26.1: The Complete Guide in the parsing schema (tables, triggers, package, views, and sample data), and gives you the roles of the application. If the schema already has the Orbit tables, they are left as they are.'
,p_install_success_message=>'Orbit Sales is ready. Run the application and sign in with your workspace user name and password.'
,p_install_failure_message=>'Some supporting objects could not be installed; see the README of the book''s code repository. You can give yourself access in Shared Components > Application Access Control.'
,p_deinstall_success_message=>'The Orbit Outfitters sample schema was removed.'
,p_deinstall_script_clob=>wwv_flow_imp.varchar2_to_clob(wwv_flow_imp.g_varchar2_table)
);
end;
/
prompt --application/deployment/install/install_check_the_schema
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '-- Records what the installation finds: Orbit tables already installed (ORB_SETUP_SKIP),'||chr(10);
wwv_flow_imp.g_varchar2_table(2) := '-- and a database without BOOLEAN columns and duality views (ORB_SETUP_19C).'||chr(10);
wwv_flow_imp.g_varchar2_table(3) := 'declare'||chr(10);
wwv_flow_imp.g_varchar2_table(4) := '    l_count number;'||chr(10);
wwv_flow_imp.g_varchar2_table(5) := 'begin'||chr(10);
wwv_flow_imp.g_varchar2_table(6) := '    for t in (select table_name from user_tables where table_name in (''ORB_SETUP_SKIP'', ''ORB_SETUP_19C'')) loop'||chr(10);
wwv_flow_imp.g_varchar2_table(7) := '        execute immediate ''drop table '' || t.table_name || '' purge'';'||chr(10);
wwv_flow_imp.g_varchar2_table(8) := '    end loop;'||chr(10);
wwv_flow_imp.g_varchar2_table(9) := '    select count(*) into l_count from user_tables where table_name = ''ORB_CUSTOMERS'';'||chr(10);
wwv_flow_imp.g_varchar2_table(10) := '    if l_count > 0 then'||chr(10);
wwv_flow_imp.g_varchar2_table(11) := '        execute immediate ''create table orb_setup_skip (x number)'';'||chr(10);
wwv_flow_imp.g_varchar2_table(12) := '    end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(13) := '    if dbms_db_version.version < 23 then'||chr(10);
wwv_flow_imp.g_varchar2_table(14) := '        execute immediate ''create table orb_setup_19c (x number)'';'||chr(10);
wwv_flow_imp.g_varchar2_table(15) := '    end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(16) := 'end;'||chr(10);
wwv_flow_imp.g_varchar2_table(17) := '/'||chr(10);
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(39911000000000001)
,p_install_id=>wwv_flow_imp.id(39911000000000000)
,p_name=>'Check the schema'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_imp.varchar2_to_clob(wwv_flow_imp.g_varchar2_table)
