wwv_flow_imp.g_varchar2_table(21) := 'create or replace trigger orb_products_biu'||chr(10);
wwv_flow_imp.g_varchar2_table(22) := '    before insert or update on orb_products'||chr(10);
wwv_flow_imp.g_varchar2_table(23) := '    for each row'||chr(10);
wwv_flow_imp.g_varchar2_table(24) := 'begin'||chr(10);
wwv_flow_imp.g_varchar2_table(25) := '    if inserting then'||chr(10);
