wwv_flow_imp.g_varchar2_table(33) := '/'||chr(10);
wwv_flow_imp.g_varchar2_table(34) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(35) := 'create or replace trigger orb_orders_biu'||chr(10);
wwv_flow_imp.g_varchar2_table(36) := '    before insert or update on orb_orders'||chr(10);
wwv_flow_imp.g_varchar2_table(37) := '    for each row'||chr(10);
wwv_flow_imp.g_varchar2_table(38) := 'declare'||chr(10);
wwv_flow_imp.g_varchar2_table(39) := '    l_lines number;'||chr(10);
wwv_flow_imp.g_varchar2_table(40) := 'begin'||chr(10);
wwv_flow_imp.g_varchar2_table(41) := '    if inserting then'||chr(10);
wwv_flow_imp.g_varchar2_table(42) := '        :new.created_on := sysdate;'||chr(10);
wwv_flow_imp.g_varchar2_table(43) := '        :new.created_by := coalesce(sys_context(''APEX$SESSION'', ''APP_USER''), user);'||chr(10);
wwv_flow_imp.g_varchar2_table(44) := '    end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(45) := '    -- A new order discount changes the order total.'||chr(10);
wwv_flow_imp.g_varchar2_table(46) := '    if updating(''DISCOUNT_PCT'') then'||chr(10);
wwv_flow_imp.g_varchar2_table(47) := '        select nvl(sum(line_total), 0) into l_lines'||chr(10);
wwv_flow_imp.g_varchar2_table(48) := '          from orb_order_items'||chr(10);
wwv_flow_imp.g_varchar2_table(49) := '         where order_id = :new.order_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(50) := '        :new.order_total := round(l_lines * (1 - :new.discount_pct / 100), 2);'||chr(10);
wwv_flow_imp.g_varchar2_table(51) := '    end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(52) := '    :new.updated_on := sysdate;'||chr(10);
wwv_flow_imp.g_varchar2_table(53) := '    :new.updated_by := coalesce(sys_context(''APEX$SESSION'', ''APP_USER''), user);'||chr(10);
wwv_flow_imp.g_varchar2_table(54) := 'end orb_orders_biu;'||chr(10);
wwv_flow_imp.g_varchar2_table(55) := '/'||chr(10);
wwv_flow_imp.g_varchar2_table(56) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(57) := 'create sequence orb_order_number_seq start with 10001 nocache;'||chr(10);
wwv_flow_imp.g_varchar2_table(58) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(59) := 'create or replace package orb_sales as'||chr(10);
wwv_flow_imp.g_varchar2_table(60) := '    -- Next order number, e.g. ORD-10001.'||chr(10);
wwv_flow_imp.g_varchar2_table(61) := '    function next_order_number return varchar2;'||chr(10);
wwv_flow_imp.g_varchar2_table(62) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(63) := '    -- Recalculates ORB_ORDERS.ORDER_TOTAL from the order lines and the order discount.'||chr(10);
wwv_flow_imp.g_varchar2_table(64) := '    procedure recalc_order_total (p_order_id in number);'||chr(10);
wwv_flow_imp.g_varchar2_table(65) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(66) := '    -- Status changes with their business rules.'||chr(10);
wwv_flow_imp.g_varchar2_table(67) := '    procedure submit_order (p_order_id in number);'||chr(10);
wwv_flow_imp.g_varchar2_table(68) := '    procedure approve_order (p_order_id in number);'||chr(10);
wwv_flow_imp.g_varchar2_table(69) := '    procedure ship_order (p_order_id in number);'||chr(10);
wwv_flow_imp.g_varchar2_table(70) := '    procedure cancel_order (p_order_id in number, p_reason in varchar2 default null);'||chr(10);
wwv_flow_imp.g_varchar2_table(71) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(72) := '    -- Appends a time-stamped line to the order''s notes.'||chr(10);
wwv_flow_imp.g_varchar2_table(73) := '    procedure add_order_note (p_order_id in number, p_note in varchar2);'||chr(10);
wwv_flow_imp.g_varchar2_table(74) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(75) := '    -- Orders with a discount above this percentage need a manager''s approval.'||chr(10);
wwv_flow_imp.g_varchar2_table(76) := '    c_approval_discount_pct constant number := 10;'||chr(10);
wwv_flow_imp.g_varchar2_table(77) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(78) := '    -- Total value of a customer''s delivered and shipped orders.'||chr(10);
wwv_flow_imp.g_varchar2_table(79) := '    function customer_lifetime_value (p_customer_id in number) return number;'||chr(10);
wwv_flow_imp.g_varchar2_table(80) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(81) := '    -- Quantity of a product across all warehouses.'||chr(10);
wwv_flow_imp.g_varchar2_table(82) := '    function stock_on_hand (p_product_id in number) return number;'||chr(10);
wwv_flow_imp.g_varchar2_table(83) := 'end orb_sales;'||chr(10);
wwv_flow_imp.g_varchar2_table(84) := '/'||chr(10);
wwv_flow_imp.g_varchar2_table(85) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(86) := 'create or replace package body orb_sales as'||chr(10);
wwv_flow_imp.g_varchar2_table(87) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(88) := '    function next_order_number return varchar2 is'||chr(10);
wwv_flow_imp.g_varchar2_table(89) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(90) := '        return ''ORD-'' || orb_order_number_seq.nextval;'||chr(10);
wwv_flow_imp.g_varchar2_table(91) := '    end next_order_number;'||chr(10);
wwv_flow_imp.g_varchar2_table(92) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(93) := '    procedure recalc_order_total (p_order_id in number) is'||chr(10);
wwv_flow_imp.g_varchar2_table(94) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(95) := '        update orb_orders o'||chr(10);
wwv_flow_imp.g_varchar2_table(96) := '           set o.order_total = ('||chr(10);
wwv_flow_imp.g_varchar2_table(97) := '                   select round(nvl(sum(i.line_total), 0) * (1 - o.discount_pct / 100), 2)'||chr(10);
wwv_flow_imp.g_varchar2_table(98) := '                     from orb_order_items i'||chr(10);
wwv_flow_imp.g_varchar2_table(99) := '                    where i.order_id = o.order_id)'||chr(10);
wwv_flow_imp.g_varchar2_table(100) := '         where o.order_id = p_order_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(101) := '    end recalc_order_total;'||chr(10);
wwv_flow_imp.g_varchar2_table(102) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(103) := '    procedure set_status (p_order_id in number, p_from in apex_t_varchar2, p_to in varchar2) is'||chr(10);
wwv_flow_imp.g_varchar2_table(104) := '        l_status orb_orders.status%type;'||chr(10);
wwv_flow_imp.g_varchar2_table(105) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(106) := '        select status into l_status from orb_orders where order_id = p_order_id for update;'||chr(10);
wwv_flow_imp.g_varchar2_table(107) := '        if l_status not member of p_from then'||chr(10);
wwv_flow_imp.g_varchar2_table(108) := '            raise_application_error(-20001,'||chr(10);
wwv_flow_imp.g_varchar2_table(109) := '                ''Order cannot change from '' || l_status || '' to '' || p_to || ''.'');'||chr(10);
wwv_flow_imp.g_varchar2_table(110) := '        end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(111) := '        update orb_orders'||chr(10);
wwv_flow_imp.g_varchar2_table(112) := '           set status = p_to,'||chr(10);
wwv_flow_imp.g_varchar2_table(113) := '               shipped_date = case when p_to = ''SHIPPED'' then trunc(sysdate) else shipped_date end'||chr(10);
wwv_flow_imp.g_varchar2_table(114) := '         where order_id = p_order_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(115) := '    end set_status;'||chr(10);
wwv_flow_imp.g_varchar2_table(116) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(117) := '    procedure submit_order (p_order_id in number) is'||chr(10);
wwv_flow_imp.g_varchar2_table(118) := '        l_discount orb_orders.discount_pct%type;'||chr(10);
wwv_flow_imp.g_varchar2_table(119) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(120) := '        select discount_pct into l_discount from orb_orders where order_id = p_order_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(121) := '        set_status(p_order_id, apex_t_varchar2(''NEW''),'||chr(10);
wwv_flow_imp.g_varchar2_table(122) := '                   case when l_discount > c_approval_discount_pct'||chr(10);
wwv_flow_imp.g_varchar2_table(123) := '                        then ''PENDING_APPROVAL'' else ''APPROVED'' end);'||chr(10);
wwv_flow_imp.g_varchar2_table(124) := '    end submit_order;'||chr(10);
wwv_flow_imp.g_varchar2_table(125) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(126) := '    procedure approve_order (p_order_id in number) is'||chr(10);
wwv_flow_imp.g_varchar2_table(127) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(128) := '        set_status(p_order_id, apex_t_varchar2(''PENDING_APPROVAL''), ''APPROVED'');'||chr(10);
wwv_flow_imp.g_varchar2_table(129) := '    end approve_order;'||chr(10);
wwv_flow_imp.g_varchar2_table(130) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(131) := '    procedure ship_order (p_order_id in number) is'||chr(10);
wwv_flow_imp.g_varchar2_table(132) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(133) := '        set_status(p_order_id, apex_t_varchar2(''APPROVED''), ''SHIPPED'');'||chr(10);
wwv_flow_imp.g_varchar2_table(134) := '    end ship_order;'||chr(10);
wwv_flow_imp.g_varchar2_table(135) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(136) := '    procedure cancel_order (p_order_id in number, p_reason in varchar2 default null) is'||chr(10);
wwv_flow_imp.g_varchar2_table(137) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(138) := '        set_status(p_order_id, apex_t_varchar2(''NEW'', ''PENDING_APPROVAL'', ''APPROVED''), ''CANCELLED'');'||chr(10);
wwv_flow_imp.g_varchar2_table(139) := '        if p_reason is not null then'||chr(10);
wwv_flow_imp.g_varchar2_table(140) := '            update orb_orders'||chr(10);
wwv_flow_imp.g_varchar2_table(141) := '               set notes = substr(notes || case when notes is not null then chr(10) end'||chr(10);
wwv_flow_imp.g_varchar2_table(142) := '                                  || ''Cancelled: '' || p_reason, 1, 4000)'||chr(10);
wwv_flow_imp.g_varchar2_table(143) := '             where order_id = p_order_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(144) := '        end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(145) := '    end cancel_order;'||chr(10);
wwv_flow_imp.g_varchar2_table(146) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(147) := '    procedure add_order_note (p_order_id in number, p_note in varchar2) is'||chr(10);
wwv_flow_imp.g_varchar2_table(148) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(149) := '        update orb_orders'||chr(10);
