wwv_flow_imp.g_varchar2_table(184) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(185) := '    type t_ids is table of boolean index by pls_integer;'||chr(10);
wwv_flow_imp.g_varchar2_table(186) := '    g_orders t_ids;'||chr(10);
wwv_flow_imp.g_varchar2_table(187) := ''||chr(10);
