wwv_flow_imp.g_varchar2_table(192) := '        end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(193) := '        if deleting or updating then'||chr(10);
wwv_flow_imp.g_varchar2_table(194) := '            g_orders(:old.order_id) := true;'||chr(10);
wwv_flow_imp.g_varchar2_table(195) := '        end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(196) := '    end after each row;'||chr(10);
wwv_flow_imp.g_varchar2_table(197) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(198) := '    after statement is'||chr(10);
wwv_flow_imp.g_varchar2_table(199) := '        l_id pls_integer := g_orders.first;'||chr(10);
wwv_flow_imp.g_varchar2_table(200) := '    begin'||chr(10);
