wwv_flow_imp.g_varchar2_table(210) := '-- Added in Chapter 19: default line numbers and prices for new order lines.'||chr(10);
wwv_flow_imp.g_varchar2_table(211) := 'create or replace trigger orb_order_items_bi'||chr(10);
wwv_flow_imp.g_varchar2_table(212) := '    before insert on orb_order_items'||chr(10);
wwv_flow_imp.g_varchar2_table(213) := '    for each row'||chr(10);
wwv_flow_imp.g_varchar2_table(214) := 'begin'||chr(10);
wwv_flow_imp.g_varchar2_table(215) := '    -- Number the new line after the order''s last line.'||chr(10);
wwv_flow_imp.g_varchar2_table(216) := '    if :new.line_no is null then'||chr(10);
wwv_flow_imp.g_varchar2_table(217) := '        select nvl(max(line_no), 0) + 1'||chr(10);
