wwv_flow_imp.g_varchar2_table(227) := '         where product_id = :new.product_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(228) := '    end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(229) := 'end orb_order_items_bi;'||chr(10);
wwv_flow_imp.g_varchar2_table(230) := '/'||chr(10);
