prompt --application/deployment/install/install_users_and_password_checking_chapter_35
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := '-- Chapter 35: users and password checking for the "Orbit Users" custom authentication scheme.'||chr(10);
wwv_flow_imp.g_varchar2_table(2) := '-- Requires: grant execute on sys.dbms_crypto to orbit;'||chr(10);
wwv_flow_imp.g_varchar2_table(3) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(4) := 'create table orb_app_users ('||chr(10);
wwv_flow_imp.g_varchar2_table(5) := '    user_id        number generated always as identity primary key,'||chr(10);
wwv_flow_imp.g_varchar2_table(6) := '    username       varchar2(100 char) not null,'||chr(10);
wwv_flow_imp.g_varchar2_table(7) := '    full_name      varchar2(200 char),'||chr(10);
wwv_flow_imp.g_varchar2_table(8) := '    password_hash  raw(64)            not null,'||chr(10);
wwv_flow_imp.g_varchar2_table(9) := '    password_salt  raw(16)            not null,'||chr(10);
wwv_flow_imp.g_varchar2_table(10) := '    is_active      varchar2(1 char)   default ''Y'' not null,'||chr(10);
wwv_flow_imp.g_varchar2_table(11) := '    failed_logins  number             default 0   not null,'||chr(10);
wwv_flow_imp.g_varchar2_table(12) := '    last_login_on  date,'||chr(10);
wwv_flow_imp.g_varchar2_table(13) := '    constraint orb_app_users_uk        unique (username),'||chr(10);
wwv_flow_imp.g_varchar2_table(14) := '    constraint orb_app_users_active_ck check (is_active in (''Y'', ''N''))'||chr(10);
wwv_flow_imp.g_varchar2_table(15) := ');'||chr(10);
wwv_flow_imp.g_varchar2_table(16) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(17) := 'create or replace package orb_auth authid definer as'||chr(10);
wwv_flow_imp.g_varchar2_table(18) := '    -- Creates a user, or sets a new password for an existing one.'||chr(10);
wwv_flow_imp.g_varchar2_table(19) := '    procedure set_password ('||chr(10);
wwv_flow_imp.g_varchar2_table(20) := '        p_username  in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(21) := '        p_password  in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(22) := '        p_full_name in varchar2 default null);'||chr(10);
wwv_flow_imp.g_varchar2_table(23) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(24) := '    -- Authentication function of the custom authentication scheme.'||chr(10);
wwv_flow_imp.g_varchar2_table(25) := '    function authenticate ('||chr(10);
wwv_flow_imp.g_varchar2_table(26) := '        p_username in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(27) := '        p_password in varchar2) return boolean;'||chr(10);
wwv_flow_imp.g_varchar2_table(28) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(29) := '    -- Post-authentication procedure: records the time of the sign-in.'||chr(10);
wwv_flow_imp.g_varchar2_table(30) := '    procedure post_authenticate;'||chr(10);
wwv_flow_imp.g_varchar2_table(31) := 'end orb_auth;'||chr(10);
wwv_flow_imp.g_varchar2_table(32) := '/'||chr(10);
wwv_flow_imp.g_varchar2_table(33) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(34) := 'create or replace package body orb_auth as'||chr(10);
wwv_flow_imp.g_varchar2_table(35) := '    c_iterations   constant pls_integer := 20000;   -- PBKDF2 rounds'||chr(10);
wwv_flow_imp.g_varchar2_table(36) := '    c_max_failures constant pls_integer := 5;       -- lock after five wrong passwords'||chr(10);
wwv_flow_imp.g_varchar2_table(37) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(38) := '    -- PBKDF2 with HMAC-SHA512, one 64-byte block (RFC 8018).'||chr(10);
wwv_flow_imp.g_varchar2_table(39) := '    function pbkdf2 (p_password in varchar2, p_salt in raw) return raw is'||chr(10);
wwv_flow_imp.g_varchar2_table(40) := '        l_key raw(2000) := utl_i18n.string_to_raw(p_password, ''AL32UTF8'');'||chr(10);
wwv_flow_imp.g_varchar2_table(41) := '        l_u   raw(64);'||chr(10);
wwv_flow_imp.g_varchar2_table(42) := '        l_t   raw(64);'||chr(10);
wwv_flow_imp.g_varchar2_table(43) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(44) := '        l_u := dbms_crypto.mac(utl_raw.concat(p_salt, hextoraw(''00000001'')),'||chr(10);
wwv_flow_imp.g_varchar2_table(45) := '                               dbms_crypto.hmac_sh512, l_key);'||chr(10);
wwv_flow_imp.g_varchar2_table(46) := '        l_t := l_u;'||chr(10);
wwv_flow_imp.g_varchar2_table(47) := '        for i in 2 .. c_iterations loop'||chr(10);
wwv_flow_imp.g_varchar2_table(48) := '            l_u := dbms_crypto.mac(l_u, dbms_crypto.hmac_sh512, l_key);'||chr(10);
wwv_flow_imp.g_varchar2_table(49) := '            l_t := utl_raw.bit_xor(l_t, l_u);'||chr(10);
wwv_flow_imp.g_varchar2_table(50) := '        end loop;'||chr(10);
wwv_flow_imp.g_varchar2_table(51) := '        return l_t;'||chr(10);
wwv_flow_imp.g_varchar2_table(52) := '    end pbkdf2;'||chr(10);
wwv_flow_imp.g_varchar2_table(53) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(54) := '    -- Counts a failed attempt, even though APEX rolls back the failed sign-in.'||chr(10);
wwv_flow_imp.g_varchar2_table(55) := '    procedure record_failure (p_user_id in number) is'||chr(10);
wwv_flow_imp.g_varchar2_table(56) := '        pragma autonomous_transaction;'||chr(10);
wwv_flow_imp.g_varchar2_table(57) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(58) := '        update orb_app_users'||chr(10);
wwv_flow_imp.g_varchar2_table(59) := '           set failed_logins = failed_logins + 1'||chr(10);
wwv_flow_imp.g_varchar2_table(60) := '         where user_id = p_user_id;'||chr(10);
wwv_flow_imp.g_varchar2_table(61) := '        commit;'||chr(10);
wwv_flow_imp.g_varchar2_table(62) := '    end record_failure;'||chr(10);
wwv_flow_imp.g_varchar2_table(63) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(64) := '    procedure set_password ('||chr(10);
wwv_flow_imp.g_varchar2_table(65) := '        p_username  in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(66) := '        p_password  in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(67) := '        p_full_name in varchar2 default null)'||chr(10);
wwv_flow_imp.g_varchar2_table(68) := '    is'||chr(10);
wwv_flow_imp.g_varchar2_table(69) := '        l_salt raw(16) := dbms_crypto.randombytes(16);'||chr(10);
wwv_flow_imp.g_varchar2_table(70) := '        l_hash raw(64) := pbkdf2(p_password, l_salt);'||chr(10);
wwv_flow_imp.g_varchar2_table(71) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(72) := '        merge into orb_app_users u'||chr(10);
wwv_flow_imp.g_varchar2_table(73) := '        using (select upper(p_username) as username from dual) s'||chr(10);
wwv_flow_imp.g_varchar2_table(74) := '           on (u.username = s.username)'||chr(10);
wwv_flow_imp.g_varchar2_table(75) := '         when matched then update'||chr(10);
wwv_flow_imp.g_varchar2_table(76) := '              set u.password_hash = l_hash,'||chr(10);
wwv_flow_imp.g_varchar2_table(77) := '                  u.password_salt = l_salt,'||chr(10);
wwv_flow_imp.g_varchar2_table(78) := '                  u.failed_logins = 0,'||chr(10);
wwv_flow_imp.g_varchar2_table(79) := '                  u.full_name     = nvl(p_full_name, u.full_name)'||chr(10);
wwv_flow_imp.g_varchar2_table(80) := '         when not matched then insert (username, full_name, password_hash, password_salt)'||chr(10);
wwv_flow_imp.g_varchar2_table(81) := '              values (s.username, p_full_name, l_hash, l_salt);'||chr(10);
wwv_flow_imp.g_varchar2_table(82) := '    end set_password;'||chr(10);
wwv_flow_imp.g_varchar2_table(83) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(84) := '    function authenticate ('||chr(10);
wwv_flow_imp.g_varchar2_table(85) := '        p_username in varchar2,'||chr(10);
wwv_flow_imp.g_varchar2_table(86) := '        p_password in varchar2) return boolean'||chr(10);
wwv_flow_imp.g_varchar2_table(87) := '    is'||chr(10);
wwv_flow_imp.g_varchar2_table(88) := '        l_user orb_app_users%rowtype;'||chr(10);
wwv_flow_imp.g_varchar2_table(89) := '        l_hash raw(64);'||chr(10);
wwv_flow_imp.g_varchar2_table(90) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(91) := '        select * into l_user'||chr(10);
wwv_flow_imp.g_varchar2_table(92) := '          from orb_app_users'||chr(10);
wwv_flow_imp.g_varchar2_table(93) := '         where username = upper(p_username);'||chr(10);
wwv_flow_imp.g_varchar2_table(94) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(95) := '        l_hash := pbkdf2(p_password, l_user.password_salt);'||chr(10);
wwv_flow_imp.g_varchar2_table(96) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(97) := '        if l_user.is_active = ''N'' or l_user.failed_logins >= c_max_failures then'||chr(10);
wwv_flow_imp.g_varchar2_table(98) := '            return false;'||chr(10);
wwv_flow_imp.g_varchar2_table(99) := '        elsif l_hash = l_user.password_hash then'||chr(10);
wwv_flow_imp.g_varchar2_table(100) := '            return true;'||chr(10);
wwv_flow_imp.g_varchar2_table(101) := '        else'||chr(10);
wwv_flow_imp.g_varchar2_table(102) := '            record_failure(l_user.user_id);'||chr(10);
wwv_flow_imp.g_varchar2_table(103) := '            return false;'||chr(10);
wwv_flow_imp.g_varchar2_table(104) := '        end if;'||chr(10);
wwv_flow_imp.g_varchar2_table(105) := '    exception'||chr(10);
wwv_flow_imp.g_varchar2_table(106) := '        when no_data_found then'||chr(10);
wwv_flow_imp.g_varchar2_table(107) := '            -- Spend the same time as for a real user, so that timing does not reveal user names.'||chr(10);
wwv_flow_imp.g_varchar2_table(108) := '            l_hash := pbkdf2(p_password, hextoraw(''00''));'||chr(10);
wwv_flow_imp.g_varchar2_table(109) := '            return false;'||chr(10);
wwv_flow_imp.g_varchar2_table(110) := '    end authenticate;'||chr(10);
wwv_flow_imp.g_varchar2_table(111) := ''||chr(10);
wwv_flow_imp.g_varchar2_table(112) := '    procedure post_authenticate is'||chr(10);
wwv_flow_imp.g_varchar2_table(113) := '    begin'||chr(10);
wwv_flow_imp.g_varchar2_table(114) := '        update orb_app_users'||chr(10);
wwv_flow_imp.g_varchar2_table(115) := '           set last_login_on = sysdate,'||chr(10);
wwv_flow_imp.g_varchar2_table(116) := '               failed_logins = 0'||chr(10);
