wwv_flow_imp.g_varchar2_table(2) := 'create or replace json relational duality view orb_order_dv as'||chr(10);
wwv_flow_imp.g_varchar2_table(3) := 'select json {'||chr(10);
wwv_flow_imp.g_varchar2_table(4) := '         ''_id''         : o.order_id,'||chr(10);
wwv_flow_imp.g_varchar2_table(5) := '         ''orderNumber'' : o.order_number,'||chr(10);
wwv_flow_imp.g_varchar2_table(6) := '         ''orderDate''   : o.order_date,'||chr(10);
wwv_flow_imp.g_varchar2_table(7) := '         ''status''      : o.status,'||chr(10);
wwv_flow_imp.g_varchar2_table(8) := '         ''orderTotal''  : o.order_total  with noupdate,'||chr(10);
wwv_flow_imp.g_varchar2_table(9) := '         ''customer''    : (select json {'||chr(10);
wwv_flow_imp.g_varchar2_table(10) := '                                   ''customerId'' : c.customer_id,'||chr(10);
wwv_flow_imp.g_varchar2_table(11) := '                                   ''name''       : c.customer_name,'||chr(10);
wwv_flow_imp.g_varchar2_table(12) := '                                   ''city''       : c.city }'||chr(10);
wwv_flow_imp.g_varchar2_table(13) := '                            from orb_customers c with noinsert noupdate nodelete'||chr(10);
wwv_flow_imp.g_varchar2_table(14) := '                           where c.customer_id = o.customer_id),'||chr(10);
wwv_flow_imp.g_varchar2_table(15) := '         ''lines''       : [ select json {'||chr(10);
wwv_flow_imp.g_varchar2_table(16) := '                                   ''itemId''    : i.order_item_id,'||chr(10);
wwv_flow_imp.g_varchar2_table(17) := '                                   ''lineNo''    : i.line_no,'||chr(10);
wwv_flow_imp.g_varchar2_table(18) := '                                   ''productId'' : i.product_id,'||chr(10);
wwv_flow_imp.g_varchar2_table(19) := '                                   ''quantity''  : i.quantity,'||chr(10);
wwv_flow_imp.g_varchar2_table(20) := '                                   ''unitPrice'' : i.unit_price }'||chr(10);
wwv_flow_imp.g_varchar2_table(21) := '                             from orb_order_items i with insert update delete'||chr(10);
wwv_flow_imp.g_varchar2_table(22) := '                            where i.order_id = o.order_id ] }'||chr(10);
wwv_flow_imp.g_varchar2_table(23) := '  from orb_orders o with update;'||chr(10);
